  reg({ id: "ZoomFitCommandGroup", label: "Fit", run: () => app.commands.run(vp2.prefs.fitType === "window" ? "ZoomWindowCommand" : "FitCommand") });
  reg({ id: "ViewDisplayCommand", label: "Display Settings", kind: "ui", run: () => vp2.navbar.openMenu("display") });
