R3.SolidLoft = () => {
  const s = S2(23);
  const N = 16;
  const sq = [];
  for (let i = 0; i < N; i++) {
    const t = i / N;
    const side = Math.floor(t * 4), u = t * 4 - side, h = 6.5;
    const pts2 = [[-h, -h], [h, -h], [h, h], [-h, h]];
    const a = pts2[side], b = pts2[(side + 1) % 4];
    sq.push([a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u, 0]);
  }
  const cir = [];
  for (let i = 0; i < N; i++) {
    const a = (225 + i * 360 / N) * Math.PI / 180;
    cir.push([4.6 * Math.cos(a), 4.6 * Math.sin(a), 10]);
  }
  const rings = [];
  for (let k = 0; k <= 5; k++) {
    const t = k / 5, e = t * t * (3 - 2 * t);
    rings.push(sq.map((p, i) => [p[0] + (cir[i][0] - p[0]) * e, p[1] + (cir[i][1] - p[1]) * e, 10 * t]));
  }
  const f = loftRings(rings);
  tint(f, (n2, c, ff) => ff.tag === "top", "orange");
  s.add(f, "steel", { crease: 0.75 });
  s.raw(s.line([[-6.5, 6.5, 0], [6.5, 6.5, 0], [6.5, -6.5, 0]], C.sketch, 1.6));
  return s.svg();
};
