R3.VolFieldCreateLatticeCommand = () => {
  const s = S2(21);
  s.add(box(-7, -7, 0, 7, 7, 9), "light");
  let o = s.svg(), d = "";
  for (let i = 1; i < 4; i++) {
    const u = -7 + 3.5 * i;
    for (const seg of [[[u, -7, 9], [u, 7, 9]], [[-7, u, 9], [7, u, 9]], [[7, u, 0], [7, u, 9]], [[u, 7, 0], [u, 7, 9]]]) {
      const a = s.P(seg[0]), b = s.P(seg[1]);
      d += `M${a[0]} ${a[1]}L${b[0]} ${b[1]}`;
    }
    const z = 9 * (i / 4);
    for (const seg of [[[7, -7, z], [7, 7, z]], [[-7, 7, z], [7, 7, z]]]) {
      const a = s.P(seg[0]), b = s.P(seg[1]);
      d += `M${a[0]} ${a[1]}L${b[0]} ${b[1]}`;
    }
  }
  o += pa(d, null, C.blue, 1);
  return o;
};
R3.VolFieldTextureCommand = () => {
  const s = S2(21);
  s.add(box(-7, -7, 0, 7, 7, 9));
  let o = s.svg();
  for (let i = -5; i <= 5; i += 3.3) for (let j = -5; j <= 5; j += 3.3) {
    const p = s.P([i, j, 9]);
    o += elp(p[0], p[1], 1.2, 0.75, C.blue, C.blueEdge, 0.5);
  }
  for (let i = -5; i <= 5; i += 3.3) for (let z = 1.8; z < 9; z += 3) {
    const p = s.P([7, i, z]);
    o += elp(p[0], p[1], 0.75, 1, C.blue, C.blueEdge, 0.5);
    const q = s.P([i, 7, z]);
    o += elp(q[0], q[1], 0.75, 1, C.blue, C.blueEdge, 0.5);
  }
  return o;
};
R3.VolFieldModifyModelCommand = () => {
  const s = S2(21);
  const f = box(-7, -7, 0, 7, 7, 9);
  s.add(f);
  let o = s.svg();
  const bands = ["#e5483d", "#f2a541", "#f6dc54", "#7ac74f", "#3d8fd9"];
  bands.forEach((col, i) => {
    const z0 = 9 * i / 5, z1 = 9 * (i + 1) / 5;
    o += pg([s.P([7, -7, z0]), s.P([7, 7, z0]), s.P([7, 7, z1]), s.P([7, -7, z1])], col, null, 1, { "fill-opacity": 0.65 });
    o += pg([s.P([-7, 7, z0]), s.P([7, 7, z0]), s.P([7, 7, z1]), s.P([-7, 7, z1])], col, null, 1, { "fill-opacity": 0.45 });
  });
  return o + pl([s.P([-7, 7, 0]), s.P([7, 7, 0]), s.P([7, -7, 0])], C.edge, 1);
};
