function zebraClip() {
  let d = "";
  for (let i = 0; i < 4; i++) {
    const y0 = 7 + i * 5.4;
    const pts2 = [];
    for (let x = 5; x <= 27; x += 1) {
      const y = y0 + 2.2 * Math.sin((x - 5) / 4);
      if ((x - 16) ** 2 + (y - 16) ** 2 < 118) pts2.push([x, y]);
    }
    const pts22 = [];
    for (let x = 27; x >= 5; x -= 1) {
      const y = y0 + 2.6 + 2.2 * Math.sin((x - 5) / 4);
      if ((x - 16) ** 2 + (y - 16) ** 2 < 118) pts22.push([x, y]);
    }
    if (pts2.length > 1 && pts22.length > 1) d += pg([...pts2, ...pts22], "#2b3540", null);
  }
  return d;
}
