R3.FusionIsoCurveAnalysisCommand = () => {
  const s = S2(22);
  const N = 6, sheet3 = [];
  const z = (x, y) => 4 + 2.4 * Math.sin((x + 8) / 16 * Math.PI) + 1.2 * Math.cos((y + 8) / 16 * Math.PI * 1.5);
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const x0 = -8 + 16 * i / N, x1 = -8 + 16 * (i + 1) / N, y0 = -8 + 16 * j / N, y1 = -8 + 16 * (j + 1) / N;
    sheet3.push([[x0, y0, z(x0, y0)], [x1, y0, z(x1, y0)], [x1, y1, z(x1, y1)], [x0, y1, z(x0, y1)]]);
  }
  s.add(sheet3, "light", { two: true, crease: 0.7 });
  let o = s.svg();
  for (let i = 1; i < N; i++) {
    const u = -8 + 16 * i / N, a = [], b = [];
    for (let k = 0; k <= 12; k++) {
      const v = -8 + 16 * k / 12;
      a.push(s.P([u, v, z(u, v)]));
      b.push(s.P([v, u, z(v, u)]));
    }
    o += pl(a, C.blue, 0.9) + pl(b, C.blue, 0.9);
  }
  return o;
};
