var R4 = {};
var ink = (pts2, w = 1.5) => pl(pts2, C.ink, w);
var inkDash = (pts2) => pl(pts2, C.inkLight, 1.1, dash(2, 1.5));
var centerLine = (pts2) => pl(pts2, C.ink, 0.9, dash(4, 1.4));
var pts = (...ps) => ps.map(([x, y]) => spt(x, y)).join("");
var circle = (cx, cy, r, fill2 = C.profile) => ci(cx, cy, r, fill2, C.sketch, 1.6);
function through(P, n2 = 8) {
  const out = [];
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(P.length - 1, i + 2)];
    for (let k = 0; k < n2; k++) {
      const t = k / n2, t2 = t * t, t3 = t2 * t;
      out.push([0, 1].map((j) => 0.5 * (2 * p1[j] + (-p0[j] + p2[j]) * t + (2 * p0[j] - 5 * p1[j] + 4 * p2[j] - p3[j]) * t2 + (-p0[j] + 3 * p1[j] - 3 * p2[j] + p3[j]) * t3)));
    }
  }
  out.push(P[P.length - 1]);
  return out;
}
function bspline(P, n2 = 8) {
  const Q2 = [P[0], P[0], ...P, P[P.length - 1], P[P.length - 1]];
  const out = [];
  for (let i = 0; i < Q2.length - 3; i++) for (let k = 0; k <= n2; k++) {
    const t = k / n2, b0 = (1 - t) ** 3 / 6, b1 = (3 * t ** 3 - 6 * t * t + 4) / 6, b2 = (-3 * t ** 3 + 3 * t * t + 3 * t + 1) / 6, b3 = t ** 3 / 6;
    out.push([0, 1].map((j) => b0 * Q2[i][j] + b1 * Q2[i + 1][j] + b2 * Q2[i + 2][j] + b3 * Q2[i + 3][j]));
  }
  return out;
}
var tri = (x, y, s = 3.2, fill2 = C.cons) => pg([[x, y - s], [x + s * 0.95, y + s * 0.6], [x - s * 0.95, y + s * 0.6]], fill2, C.sketchDark, 0.8);
