  for (let i = 0; i <= 8; i++) loop.push(s.P([9, -9 + 18 * i / 8, z(9, -9 + 18 * i / 8)]));
  for (let i = 0; i <= 8; i++) loop.push(s.P([9 - 18 * i / 8, 9, z(9 - 18 * i / 8, 9)]));
  for (let i = 0; i <= 8; i++) loop.push(s.P([-9, 9 - 18 * i / 8, z(-9, 9 - 18 * i / 8)]));
